WITH causal_seed(payload) AS (
  VALUES ('{"chain":"Aptos","sources":[{"id":"aptos-execution","title":"Aptos execution and Block-STM","publisher":"Aptos Foundation","url":"https://aptos.dev/network/blockchain/execution.md","source_role":"primary","checked_at":"2026-08-03"},{"id":"aptos-staking","title":"Aptos staking, validator, and voter model","publisher":"Aptos Foundation","url":"https://aptos.dev/network/blockchain/staking.md","source_role":"primary","checked_at":"2026-08-03"},{"id":"aptos-core-releases","title":"Aptos Core mainnet releases","publisher":"Aptos Labs","url":"https://github.com/aptos-labs/aptos-core/releases","source_role":"primary","checked_at":"2026-08-03"},{"id":"aptos-core","title":"Aptos Core implementation","publisher":"Aptos Labs","url":"https://github.com/aptos-labs/aptos-core","source_role":"primary","checked_at":"2026-08-03"},{"id":"aptos-tvl","title":"Aptos historical TVL API","publisher":"DefiLlama","url":"https://api.llama.fi/v2/historicalChainTvl/Aptos","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"aptos-fees","title":"Aptos fees API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/fees/Aptos?dataType=dailyFees","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"aptos-revenue","title":"Aptos revenue API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/fees/Aptos?dataType=dailyRevenue","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"aptos-volume","title":"Aptos DEX volume API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/dexs/Aptos?dataType=dailyVolume","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"stablecoin-chains","title":"Stablecoin supply by chain API","publisher":"DefiLlama","url":"https://stablecoins.llama.fi/stablecoinchains","source_role":"independent-data","checked_at":"2026-08-03"}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T17:20:28.274Z","provider":"DefiLlama","method":"Single sequential API run using the latest historicalChainTvl point, provider-reported 30-day fee/revenue/DEX aggregates, and current stablecoinchains values. The historical TVL point is dated 2026-08-03 and can be revised after this retrieval time.","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":61837836,"peak_tvl_usd":1305084571,"peak_tvl_date":"2024-12-17","tvl_drawdown_pct":95.26,"stablecoin_supply":{"pegged_usd":1181631996.8585446},"dex_volume_30d_usd":801825770.13,"fees_30d_usd":738763.27,"revenue_30d_usd":440499.22,"observation_completed_at":"2026-08-03T17:20:30.954Z"},"outcome":{"label":"middling","summary":"Aptos is a middling L1 with a large stablecoin footprint but weak capital retention and fee capture. In the DefiLlama API snapshot fetched at 2026-08-03T17:20:28.274Z, the latest 2026-08-03 historical point was $61.8 million TVL, 95.3% below its December 2024 peak, alongside roughly $1.18 billion of dollar stablecoins, $801.8 million of 30-day DEX volume, $738,763 of 30-day fees, and $440,499 of 30-day revenue. The stablecoin and trading observations show active rails; they do not by themselves establish payment adoption, institutional settlement, or proportionate APT value capture. These figures are a point-in-time snapshot.","confidence":"high","as_of":"2026-08-03","source_refs":["aptos-tvl","aptos-fees","aptos-revenue","aptos-volume","stablecoin-chains"]},"why":{"summary":"Observed: Aptos carries far more stablecoin supply and monthly DEX volume than DeFi TVL, while current fees and revenue remain small and TVL is more than 95% below peak. Documented design: it chose Move resources, deterministic Block-STM parallel execution, stake-weighted BFT, separable owner/operator/voter roles, and governance-controlled network parameters rather than EVM compatibility. Strategic inference: this stack is well suited to high-throughput financial rails and lets custodians, operators, and governance voters separate responsibilities, which can help institutional integrations. The same choices do not solve distribution or value capture: a one-million-APT validator minimum raises concentration questions, current documentation says slashing is not implemented, and low-cost throughput can produce impressive activity without much fee burn or native liquidity.","confidence":"medium","source_refs":["aptos-execution","aptos-staking","aptos-core","aptos-core-releases","aptos-tvl","aptos-fees","aptos-revenue","aptos-volume","stablecoin-chains"]},"strategic_choices":[{"decision":"Use Move resources and Block-STM dynamic parallel execution instead of an EVM-compatible sequential execution environment.","consequence":"Developers can write expressive transactions without predeclaring conflicts and the runtime extracts concurrency, while Aptos must build a separate language, tooling, application, and liquidity ecosystem.","confidence":"high","source_refs":["aptos-execution","aptos-core"]},{"decision":"Separate stake ownership, node operation, and governance voting into distinct onchain roles.","consequence":"Custodians and delegators can assign operational and voting duties without transferring ownership, but beneficial control can be obscured across owners, operators, voters, and staking services.","confidence":"high","source_refs":["aptos-staking"]},{"decision":"Require high stake for direct validation and use stake-weighted leader selection while leaving slashing unimplemented in the documented current design.","consequence":"The model can prioritize a performant professional validator set and reward proposing leaders, but a one-million-APT entry threshold and absent slashing create unresolved concentration and accountability trade-offs.","confidence":"high","source_refs":["aptos-staking"]},{"decision":"Prioritize very low-cost, high-throughput financial activity and change economics through governance and rolling mainnet upgrades.","consequence":"Stablecoin and trading rails can operate cheaply and the implementation can tune fees and performance, while the current gap between activity, TVL, fees, and revenue shows that throughput is not the same as durable capital or APT capture.","confidence":"medium","source_refs":["aptos-core-releases","aptos-staking","aptos-fees","aptos-revenue","aptos-volume","stablecoin-chains"]}],"counterfactual":{"summary":"EVM compatibility could have reduced developer and liquidity switching costs, but would have abandoned the Move and Block-STM differentiation that defines Aptos. Lower validator stake requirements or implemented slashing might broaden participation or accountability, yet the reviewed sources do not establish their net performance and security effects. Charging more from the beginning could have increased fee capture while weakening the low-cost payments and trading proposition. None of these alternatives is proven to have prevented the 95% TVL drawdown.","confidence":"medium","source_refs":["aptos-execution","aptos-staking","aptos-core-releases","aptos-tvl","aptos-fees","aptos-revenue"]},"watch":[{"signal":"Stablecoin supply and DEX volume reconciled with TVL, fees, retained revenue, and identifiable payment flows.","implication":"Recurring external settlement with rising revenue would support the financial-rail strategy; high supply and volume without capital retention or fees would preserve the capture gap.","source_refs":["stablecoin-chains","aptos-volume","aptos-tvl","aptos-fees","aptos-revenue"]},{"signal":"Validator owner, operator, voter, and stake concentration, including the effect of the one-million-APT minimum.","implication":"Broad independent control would reduce the concentration concern; a small set of beneficial owners or infrastructure providers would strengthen it.","source_refs":["aptos-staking"]},{"signal":"Mainnet fee, reward, slashing, and performance changes in Aptos Core releases and their measured economic effect.","implication":"Governance changes that improve revenue and security without losing recurring usage strengthen the model; parameter churn without improved economics does not.","source_refs":["aptos-core-releases","aptos-core","aptos-fees","aptos-revenue"]}],"unknowns":[{"question":"What share of Aptos stablecoin flow represents durable external payments or settlement rather than trading, bridging, or incentive routing?","resolution_trigger":"Counterparty-classified flows, recurring payment cohorts, and independently attributable fees."},{"question":"Who beneficially controls validator stake across owner, operator, voter, custodian, and delegation relationships?","resolution_trigger":"An independent entity-level stake and infrastructure map."},{"question":"When, if ever, will slashing be implemented and how would it change validator incentives?","resolution_trigger":"An enacted governance change and verified mainnet implementation."},{"question":"Can Aptos convert high-throughput financial activity into durable APT demand and revenue without pricing out the activity it targets?","resolution_trigger":"A reproducible post-change series for transactions, users, fees, burn, revenue, and retained liquidity."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}')
)
UPDATE chain_facts AS facts
SET
  data = CASE facts.dimension
    WHEN 'synthesis' THEN json_set(
      facts.data,
