WITH causal_seed(payload) AS (
  VALUES ('{"chain":"Osmosis","sources":[{"id":"osmosis-docs","title":"Osmosis documentation","publisher":"Osmosis","url":"https://docs.osmosis.zone/","source_role":"primary","checked_at":"2026-08-03"},{"id":"osmosis-about","title":"Osmosis protocol overview","publisher":"Osmosis","url":"https://osmosis.zone/","source_role":"primary","checked_at":"2026-08-03"},{"id":"osmosis-exploit","title":"Osmosis chain halted amid possible $5 million exploit","publisher":"CoinDesk","url":"https://www.coindesk.com/business/2022/06/08/osmosis-chain-halted-amid-possible-5m-exploit","source_role":"independent","checked_at":"2026-08-03"},{"id":"osmosis-terra-context","title":"Anatomy of a stablecoin''s failure: the Terra-Luna case","publisher":"arXiv","url":"https://arxiv.org/abs/2207.13914","source_role":"independent-research","checked_at":"2026-08-03"},{"id":"osmosis-tvl","title":"DefiLlama Osmosis historical TVL API","publisher":"DefiLlama","url":"https://api.llama.fi/v2/historicalChainTvl/Osmosis","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"osmosis-fees","title":"DefiLlama Osmosis fees API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/fees/Osmosis?dataType=dailyFees","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"osmosis-revenue","title":"DefiLlama Osmosis revenue API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/fees/Osmosis?dataType=dailyRevenue","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"osmosis-volume","title":"DefiLlama Osmosis DEX volume API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/dexs/Osmosis?dataType=dailyVolume","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"osmosis-stables","title":"DefiLlama stablecoin supply by chain API","publisher":"DefiLlama","url":"https://stablecoins.llama.fi/stablecoinchains","source_role":"independent-data","checked_at":"2026-08-03"}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T17:23:37.879Z","observation_completed_at":"2026-08-03T17:23:58.550Z","provider":"DefiLlama","method":"One sequential client run: stablecoinchains once, then the latest historicalChainTvl point and provider-reported 24-hour and 30-day fee, revenue, and DEX aggregates for each chain. Currency aggregates were rounded to cents. Same-day historical points can be revised after this retrieval window.","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":12340355,"peak_tvl_usd":1831730122,"peak_tvl_date":"2022-03-03","tvl_drawdown_pct":99.33,"stablecoin_supply":{"pegged_usd":28317022.093283202,"pegged_var":8836.61483799707},"dex_volume_24h_usd":696752,"dex_volume_30d_usd":45163607,"fees_24h_usd":1440,"fees_30d_usd":29934,"revenue_24h_usd":596.93,"revenue_30d_usd":11430.65},"outcome":{"label":"declining","summary":"Osmosis is a declining but still operating exchange appchain. In the DefiLlama snapshot begun at 2026-08-03T17:23:37.879Z, the latest 2026-08-03 point was $12.3 million TVL, 99.3% below the March 2022 peak, alongside $28.3 million of dollar stablecoins, $45.2 million of 30-day DEX volume, $29,934 of fees, and $11,431 of retained revenue. Continued routing and trading show that the product has not disappeared, but capital retention and security-budget economics are far below the incentive-era peak. The 2022 pool-accounting exploit and validator halt remain material evidence about application-chain emergency coordination. These figures are a point-in-time snapshot.","confidence":"high","as_of":"2026-08-03","source_refs":["osmosis-tvl","osmosis-stables","osmosis-volume","osmosis-fees","osmosis-revenue","osmosis-exploit"]},"why":{"summary":"Observed: Osmosis still clears trades and retains stablecoin liquidity, but TVL is more than ninety-nine percent below peak and current fees and revenue are small. Documented design: it launched as a sovereign Cosmos exchange chain so governance could control pools, routing, incentives, fee logic, upgrades, and IBC integrations at the protocol level. Strategic inference: specialization and IBC made Osmosis a natural venue for fragmented Cosmos assets, while OSMO emissions accelerated liquidity formation. Those choices did not make liquidity permanent: incentive sensitivity, the Terra ecosystem shock, fragmented interchain demand, and an independent validator security budget all pressure retention. The 2022 exploit provides direct evidence that a pool-accounting defect could become chain-wide and that validators could coordinate a halt; it does not by itself prove the later drawdown, which must remain an unattributed observed outcome rather than a single-cause story.","confidence":"medium","source_refs":["osmosis-docs","osmosis-about","osmosis-exploit","osmosis-terra-context","osmosis-tvl","osmosis-stables","osmosis-volume","osmosis-fees","osmosis-revenue"]},"strategic_choices":[{"decision":"Build a sovereign appchain around exchange execution rather than deploy an AMM on a shared chain.","consequence":"Governance can control routing, fees, upgrades, and market primitives, while the protocol must maintain its own validator security and operational stack.","confidence":"high","source_refs":["osmosis-docs","osmosis-about"]},{"decision":"Use IBC as the primary asset-distribution and interoperability rail.","consequence":"Many Cosmos assets can reach a common venue, but relayer outages, connected-zone failures, and ecosystem fragmentation become demand and safety dependencies.","confidence":"high","source_refs":["osmosis-docs"]},{"decision":"Use OSMO governance and incentives to bootstrap and direct liquidity.","consequence":"Pools can form quickly and community governance can target emissions, but mercenary capital can leave when rewards or token prices weaken.","confidence":"medium","source_refs":["osmosis-docs","osmosis-tvl"]},{"decision":"Coordinate a validator halt after the 2022 pool-share accounting exploit.","consequence":"The network limited further loss and enabled recovery, while demonstrating that validator coordination and application logic are part of the same systemic boundary.","confidence":"high","source_refs":["osmosis-exploit"]}],"counterfactual":{"summary":"Launching as contracts on a larger shared chain could have reduced the independent security and validator burden and placed Osmosis closer to a deeper base of collateral, but would sacrifice protocol-level control over exchange execution and IBC-native routing. Using fewer incentives might have produced a smaller, more organic initial liquidity base, but could also have prevented Osmosis from becoming a Cosmos hub. The reviewed evidence cannot establish that either alternative would have survived Terra contagion better or retained more long-run volume.","confidence":"medium","source_refs":["osmosis-docs","osmosis-about","osmosis-exploit","osmosis-terra-context","osmosis-tvl","osmosis-volume"]},"watch":[{"signal":"TVL, stablecoin supply, DEX volume, fees, and retained revenue, with incentive spending reported separately.","implication":"Revenue and capital growth without higher subsidies would support a recovery; volume that depends on emissions would leave the retention problem intact.","source_refs":["osmosis-tvl","osmosis-stables","osmosis-volume","osmosis-fees","osmosis-revenue"]},{"signal":"Validator voting-power concentration, security budget, and emergency-halt participation.","implication":"A diverse set with adequate economics reduces coordinated-failure risk; concentration or falling rewards would weaken sovereign-chain resilience.","source_refs":["osmosis-docs","osmosis-exploit"]},{"signal":"IBC route diversity, relayer concentration, and share of volume tied to a few connected zones.","implication":"Broader routes would make the hub less dependent on any one ecosystem; concentration would preserve contagion risk.","source_refs":["osmosis-docs","osmosis-volume"]}],"unknowns":[{"question":"What share of current volume and TVL is directly or indirectly incentive-dependent?","resolution_trigger":"A pool-level subsidy, liquidity, and organic-volume decomposition."},{"question":"How concentrated are validator voting power, hosting, and governance participation?","resolution_trigger":"A current independent entity-level validator map."},{"question":"Which IBC routes and relayers carry most economic value and how often do they fail?","resolution_trigger":"Longitudinal route-level value, relayer, and outage telemetry."},{"question":"Which applications and pools generate current protocol revenue, and how much accrues to OSMO holders or the community pool?","resolution_trigger":"A reconciled fee-flow and value-accrual statement."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}')
)
UPDATE chain_facts AS facts
SET
  data = CASE facts.dimension
    WHEN 'synthesis' THEN json_set(
      facts.data,
      '$.forensic_analysis',
      json(json_extract((SELECT payload FROM causal_seed), '$.forensic_analysis'))
    )
    WHEN '_meta' THEN json_set(
      facts.data,
      '$.forensic_analysis_version', 'forensic-analysis-v1',
      '$.last_reviewed', '2026-08-03',
      '$.next_review_at',
      json_extract(
        (SELECT payload FROM causal_seed),
        '$.forensic_analysis.review.next_review_at'
      )
    )
    ELSE facts.data
  END
  ,
  sources = CASE
    WHEN facts.dimension = 'synthesis' THEN (
      SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_set(
                json_patch(old_source.value, new_source.value),
                '$.checked_at',
                CASE
                  WHEN json_extract(old_source.value, '$.checked_at')
                    > json_extract(new_source.value, '$.checked_at')
                    THEN json_extract(old_source.value, '$.checked_at')
                  ELSE COALESCE(
                    json_extract(new_source.value, '$.checked_at'),
                    json_extract(old_source.value, '$.checked_at')
                  )
                END
              )
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(
            json_extract((SELECT payload FROM causal_seed), '$.sources')
          ) AS new_source
            ON json_extract(new_source.value, '$.url')
              = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
            OR old_source.key = (
              SELECT MIN(candidate.key)
              FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
              WHERE json_extract(candidate.value, '$.url')
                = json_extract(old_source.value, '$.url')
            )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(
            json_extract((SELECT payload FROM causal_seed), '$.sources')
          ) AS new_source
          WHERE NOT EXISTS (
            SELECT 1
            FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url')
              = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )
    )
    ELSE facts.sources
  END
  ,
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM causal_seed), '$.chain')
  AND facts.dimension IN ('synthesis', '_meta');
-- canonical-case-end Osmosis

