WITH causal_seed(payload) AS (
  VALUES ('{"chain":"Stacks","sources":[{"id":"stacks-nakamoto","title":"What was the Nakamoto upgrade?","publisher":"Stacks Documentation","url":"https://docs.stacks.co/learn/block-production/what-was-the-nakamoto-upgrade","source_role":"primary","checked_at":"2026-08-03"},{"id":"stacks-block-production","title":"Stacks block production","publisher":"Stacks Documentation","url":"https://docs.stacks.co/learn/block-production","source_role":"primary","checked_at":"2026-08-03"},{"id":"stacks-sbtc","title":"sBTC FAQ","publisher":"Stacks Documentation","url":"https://docs.stacks.co/learn/sbtc/sbtc-faq","source_role":"primary","checked_at":"2026-08-03"},{"id":"stacks-sbtc-deposit","title":"sBTC deposit operation","publisher":"Stacks Documentation","url":"https://docs.stacks.co/learn/sbtc/sbtc-operations/deposit","source_role":"primary","checked_at":"2026-08-03"},{"id":"stacks-upgrade-independent","title":"Stacks begins Nakamoto upgrade","publisher":"CoinDesk","url":"https://www.coindesk.com/tech/2024/08/28/bitcoin-layer-2-network-stacks-begins-nakamoto-upgrade/","source_role":"independent","checked_at":"2026-08-03"},{"id":"stacks-stall","title":"July 8, 2025 stall post-mortem","publisher":"Stacks Forum","url":"https://forum.stacks.org/t/july-8-2025-stall-post-mortem/18196","source_role":"primary-incident","checked_at":"2026-08-03"},{"id":"stacks-tvl","title":"DefiLlama Stacks historical TVL API","publisher":"DefiLlama","url":"https://api.llama.fi/v2/historicalChainTvl/Stacks","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"stacks-fees","title":"DefiLlama Stacks fees API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/fees/Stacks?dataType=dailyFees","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"stacks-revenue","title":"DefiLlama Stacks revenue API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/fees/Stacks?dataType=dailyRevenue","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"stacks-volume","title":"DefiLlama Stacks DEX volume API","publisher":"DefiLlama","url":"https://api.llama.fi/overview/dexs/Stacks?dataType=dailyVolume","source_role":"independent-data","checked_at":"2026-08-03"},{"id":"stacks-stables","title":"DefiLlama stablecoin supply by chain API","publisher":"DefiLlama","url":"https://stablecoins.llama.fi/stablecoinchains","source_role":"independent-data","checked_at":"2026-08-03"}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T17:23:37.879Z","observation_completed_at":"2026-08-03T17:23:58.550Z","provider":"DefiLlama","method":"One sequential client run: stablecoinchains once, then the latest historicalChainTvl point and provider-reported 24-hour and 30-day fee, revenue, and DEX aggregates for each chain. Currency aggregates were rounded to cents. Same-day historical points can be revised after this retrieval window.","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":75946342,"peak_tvl_usd":194193202,"peak_tvl_date":"2024-04-09","tvl_drawdown_pct":60.89,"stablecoin_supply":{"pegged_usd":12263284.167146854},"dex_volume_24h_usd":236592,"dex_volume_30d_usd":21415072,"fees_24h_usd":2383.64,"fees_30d_usd":74756.39,"revenue_24h_usd":403.2,"revenue_30d_usd":16403.47},"outcome":{"label":"middling","summary":"Stacks is a technically distinct but middling Bitcoin-linked smart-contract network. In the DefiLlama snapshot begun at 2026-08-03T17:23:37.879Z, the latest 2026-08-03 point was $75.9 million TVL, 60.9% below the April 2024 peak, alongside $12.3 million of dollar stablecoins, $21.4 million of 30-day DEX volume, $74,756 of fees, and $16,403 of retained revenue. Nakamoto block production and sBTC make the Bitcoin application thesis more usable, but current independent activity remains modest and the July 2025 stall shows that signer and node upgrade coordination can interrupt liveness. These figures are a point-in-time snapshot.","confidence":"high","as_of":"2026-08-03","source_refs":["stacks-tvl","stacks-stables","stacks-volume","stacks-fees","stacks-revenue","stacks-stall"]},"why":{"summary":"Observed: Stacks retains meaningful TVL but modest stablecoin, DEX, fee, and revenue activity relative to larger smart-contract ecosystems. Documented design: proof of transfer anchors miner selection and settlement to Bitcoin; Nakamoto allows multiple faster Stacks blocks during a Bitcoin tenure and adds signer validation; Clarity makes contract behavior deliberately explicit; and sBTC uses a threshold signer set to move BTC into programmable applications. Strategic inference: the architecture can offer Bitcoin-linked finality and BTC-denominated collateral without changing Bitcoin itself, which differentiates Stacks from generic EVM execution. The cost is a layered dependency on Bitcoin blocks, miners, stackers/signers, node software, and the sBTC wallet. The July 2025 stall, caused by outdated large signers encountering a known reorg-related bug, directly demonstrates coordination and upgrade risk. It does not prove the Bitcoin-layer strategy caused weak adoption, so current metrics remain outcome evidence rather than causal proof.","confidence":"medium","source_refs":["stacks-nakamoto","stacks-block-production","stacks-sbtc","stacks-sbtc-deposit","stacks-upgrade-independent","stacks-stall","stacks-tvl","stacks-volume","stacks-fees","stacks-revenue"]},"strategic_choices":[{"decision":"Use proof of transfer and Bitcoin anchoring instead of launching an independent proof-of-stake security system.","consequence":"Stacks reuses Bitcoin blocks and BTC commitments for ordering and settlement context, while retaining its own miners, signers, execution, and liveness risks.","confidence":"high","source_refs":["stacks-nakamoto","stacks-block-production"]},{"decision":"Adopt Nakamoto block production with signer-approved blocks inside each Bitcoin tenure.","consequence":"Transactions can confirm faster and gain stronger reorg resistance, but signer participation and timely node upgrades become critical liveness dependencies.","confidence":"high","source_refs":["stacks-nakamoto","stacks-upgrade-independent","stacks-stall"]},{"decision":"Use Clarity and a distinct execution environment rather than EVM compatibility.","consequence":"Developers gain decidable contracts and Bitcoin-aware primitives, while portability, tooling, and liquidity composition are narrower than in EVM ecosystems.","confidence":"medium","source_refs":["stacks-block-production","stacks-tvl","stacks-volume"]},{"decision":"Bridge BTC through sBTC threshold signers selected for an initial staged rollout.","consequence":"BTC becomes programmable without a centralized custodian, but custody and withdrawal liveness depend on a bounded signer set whose decentralization is still evolving.","confidence":"high","source_refs":["stacks-sbtc","stacks-sbtc-deposit"]}],"counterfactual":{"summary":"Building as an EVM sidechain or rollup could have imported more tooling and liquidity, but would weaken Stacks'' differentiated Clarity and proof-of-transfer design and still require a BTC bridge. Waiting for a fully open sBTC signer set before launch could reduce concentration concerns, while delaying the collateral primitive needed to test Bitcoin DeFi. Keeping pre-Nakamoto block production would avoid new signer complexity but retain slow confirmation and congestion. The evidence identifies these trade-offs without proving an alternative would have delivered more usage or perfect liveness.","confidence":"medium","source_refs":["stacks-nakamoto","stacks-block-production","stacks-sbtc","stacks-upgrade-independent","stacks-stall","stacks-tvl"]},"watch":[{"signal":"TVL, sBTC supply, stablecoins, DEX volume, fees, and retained revenue tracked separately.","implication":"Growth in BTC collateral and recurring revenue would validate more of the Bitcoin-application thesis; TVL without usage would leave capital efficiency unresolved.","source_refs":["stacks-sbtc","stacks-tvl","stacks-stables","stacks-volume","stacks-fees","stacks-revenue"]},{"signal":"Signer-set size, entity diversity, software-version adoption, missed signatures, and stalls.","implication":"Broad, current participation would reduce liveness concentration; repeated failures among a few large signers would make coordination the binding risk.","source_refs":["stacks-block-production","stacks-stall"]},{"signal":"sBTC deposit and withdrawal caps, completion times, signer rotations, and failed requests.","implication":"Reliable two-way conversion under rising balances supports the bridge design; delayed withdrawals or concentrated signers increase custody-risk weight.","source_refs":["stacks-sbtc","stacks-sbtc-deposit"]}],"unknowns":[{"question":"How concentrated are Stacks miners, Nakamoto signers, and the infrastructure they operate?","resolution_trigger":"A current independent entity-level mining, signer, and hosting map."},{"question":"What share of TVL is sBTC and how concentrated is it by protocol and depositor?","resolution_trigger":"A reproducible asset- and holder-level TVL decomposition."},{"question":"How often do signer disagreement, outdated software, or Bitcoin reorg handling delay blocks?","resolution_trigger":"Public longitudinal signer and liveness telemetry."},{"question":"How do gross fees, miner rewards, signer rewards, and STX value accrual reconcile?","resolution_trigger":"A complete independently reproducible fee and reward-flow statement."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}')
)
UPDATE chain_facts AS facts
